(() => {
 const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
 q('header>nav').addEventListener('click',e=>{if(e.target.closest('a')){q('header>nav').classList.remove('open');q('#menu').setAttribute('aria-expanded','false');q('#menu').setAttribute('aria-label','Open navigation');}});
 const steps=[
 ['APPLICATION PLANE','Define what the network should do.','Applications and experiment orchestration express the intended behavior. In a logically centralized SDN design, controller software turns that intent into forwarding decisions. This top layer is conceptual; it does not claim a specific application API in the paper.','The application sets the goal. The controller works out how the network should carry it out.','No example forwarding rule installed yet.',['arch-app','arch-controller','arch-intent']],
 ['DATA PLANE','A host sends a packet.','Host H1 sends a packet toward Host H2. Switch S1 checks its flow table for a matching rule. For this example, assume there is no matching forwarding entry.','The switch first looks for an instruction it already knows.','Lookup: destination H2 → no matching forwarding entry.',['arch-host-1','arch-switch-1','arch-data-left']],
 ['CONTROL PLANE','The switch asks the controller.','With a table-miss rule configured to send unmatched traffic to the controller, S1 sends a Packet-In message. Ryu’s application can inspect the event and decide how to handle the flow.','If the switch has no matching rule, it can ask Ryu what to do.','Table-miss behavior in this example: send a Packet-In to the controller.',['arch-switch-1','arch-controller','arch-channel-1']],
 ['CONTROL → DATA PLANE','Ryu programs the switches.','The controller can install forwarding entries using Flow-Mod messages. In this teaching example, S1 forwards traffic toward S2 and S2 forwards it toward H2. Handling the first buffered packet may also involve Packet-Out or buffer references.','Ryu gives the switches instructions. The switches store those instructions in their flow tables.','Example only: match destination H2 → output toward the next hop.',['arch-controller','arch-switch-1','arch-switch-2','arch-channel-1','arch-channel-2']],
 ['DATA PLANE','The switches forward the traffic.','Once the forwarding entries exist, matching packets travel through S1 and S2 to H2. They do not need to visit the controller for every packet. Rules have match conditions, actions, and potentially timeouts.','The controller makes the decision; the switches do the forwarding.','Matching packets: H1 → S1 → S2 → H2, while the entries remain valid.',['arch-host-1','arch-switch-1','arch-switch-2','arch-host-2','arch-data-left','arch-data-middle','arch-data-right']],
 ['OBSERVATION & RESEARCH','Collect evidence, then evaluate.','The controller can request flow statistics and receive counter information. The research combines aligned telemetry with experiment events and phase evidence to build observations. Dataset preparation and ML evaluation are a later research pipeline, not the packet-forwarding path.','We record what happened in the network, preserve its context, and then evaluate the dataset and models.','Flow entries expose counters; a label still needs evidence and context.',['arch-switch-1','arch-switch-2','arch-controller','arch-channel-1','arch-channel-2']]
 ];
 const layers=[['Application plane','Expresses intent: policies, network applications, and experiment orchestration. Think of it as the goal-setting layer. The illustrated application/controller interface is generic, not a claimed REST API or deployed service from the paper.'],['Control plane','Ryu runs controller logic and communicates with the switches using OpenFlow 1.3. Think of it as the decision-making layer. Logically centralized control does not require a single physical server in every SDN deployment.'],['Data plane','Open vSwitch forwards packets according to flow-table entries. Mininet hosts send and receive traffic. Think of it as the forwarding layer: the actual traffic path remains between endpoints through switches.']];
 let index=0,playing=false,elapsed=0,clock=0,last=0;
 function transport(){q('#arch-play').textContent=playing?'Pause explanation':'Play the explanation';q('#arch-play').setAttribute('aria-pressed',playing);}
 function select(i){index=i;elapsed=0;clock=0;const d=steps[i];q('#arch-step-label').textContent=d[0];q('#arch-step-title').textContent=d[1];q('#arch-step-body').textContent=d[2];q('#arch-say').textContent='“'+d[3]+'”';q('#arch-rule-text').textContent=d[4];q('#arch-progress').textContent=`Step ${i+1} of 6`;q('#arch-prev').disabled=i===0;q('#arch-next').disabled=i===5;all('[data-arch-step]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.archStep===i));all('#arch-diagram .arch-active').forEach(n=>n.classList.remove('arch-active'));d[5].forEach(id=>q('#'+id).classList.add('arch-active'));q('#arch-svg-desc').textContent=d[1]+' '+d[2];packet(0);}
 function manual(i){playing=false;transport();select(i);}
 all('[data-arch-step]').forEach(b=>b.addEventListener('click',()=>manual(+b.dataset.archStep)));
 q('#arch-prev').addEventListener('click',()=>manual(Math.max(0,index-1)));q('#arch-next').addEventListener('click',()=>manual(Math.min(5,index+1)));q('#arch-reset').addEventListener('click',()=>manual(0));
 q('#arch-play').addEventListener('click',()=>{if(playing){playing=false;}else{if(paused)setMotion(false);if(index===5)select(0);playing=true;}transport();});
 all('[data-arch-layer]').forEach(b=>b.addEventListener('click',()=>layer(+b.dataset.archLayer)));
 function layer(i){all('[data-arch-layer]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.archLayer===i));const title=document.createElement('h3'),p=document.createElement('p');title.textContent=layers[i][0];p.textContent=layers[i][1];q('#arch-layer-detail').replaceChildren(title,p);}
 function point(id,u,reverse=false){const path=q('#'+id);return path.getPointAtLength(path.getTotalLength()*(reverse?1-u:u));}
 function packet(ms){const p=q('#arch-packet'),u=(ms%3500)/3500;let xy;
 if(index===0)xy=point('arch-intent',u);
 if(index===1)xy=point('arch-data-left',u,true);
 if(index===2)xy=point('arch-channel-1',u,true);
 if(index===3)xy=point(u<.5?'arch-channel-1':'arch-channel-2',(u*2)%1);
 if(index===4){const part=Math.min(2,Math.floor(u*3));xy=point(['arch-data-left','arch-data-middle','arch-data-right'][part],(u*3)%1,part===0);}
 if(index===5)xy=point(u<.5?'arch-channel-1':'arch-channel-2',(u*2)%1,true);
 p.setAttribute('cx',xy.x);p.setAttribute('cy',xy.y);p.classList.toggle('arch-data-packet',index===1||index===4);
 }
 function frame(now){const dt=last?Math.min(now-last,70):0;last=now;const visible=location.hash==='#architecture'&&!document.hidden;if(visible&&!paused&&!reduceMotion.matches){clock+=dt;packet(clock);}if(playing&&visible&&!paused){elapsed+=dt;if(elapsed>=8500){if(index===5){playing=false;transport();q('#arch-progress').textContent='Explanation complete';}else select(index+1);}}requestAnimationFrame(frame);}
 addEventListener('hashchange',()=>{if(location.hash!=='#architecture'){playing=false;transport();}});select(0);layer(0);requestAnimationFrame(frame);
})();
